<include file="Public:header"/><style type="text/css">.importexcel{height: 60px;line-height: 60px;}.importexcel a{ cursor: pointer;}</style>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('User/import')}">客户导入</a>					<a href="{pigcms{:U('User/importlist')}">导入用户列表</a>                    <a href="{pigcms{:U('User/importmoney')}" class="on">客户余额导入</a>                    <a href="{pigcms{:U('User/importmoneylist')}">导入余额列表</a>				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td>						<div class="importexcel">							&nbsp;&nbsp;&nbsp;示例表格：							<a target="_blank" href="{pigcms{$config.site_url}/static/file/user/sample_money.xls">点击下载</a>							</if>						</div>					</td>				</tr>				<tr>					<td>						<div class="importexcel">						  <span>Excel导入： </span>						  <a href="javascript:;"><input type="file" title="Excel导入"  id="excelimport"  name="excelfile" value="选择文件上传"/></a>						</div>					</td>				</tr>			</table>            <form name="myform" id="myform" action="" method="post">                <div class="table-list">                    <table width="100%" cellspacing="0">                        <colgroup>                            <col/>                            <col/>                            <col/>                            <col/>                        </colgroup>                        <thead>                        <tr>                            <th>手机号</th>                            <th>余额</th>                            <th>{pigcms{$config['score_name']}</th>                            <th>备注</th>                        </tr>                        </thead>                        <tbody>                        <if condition="is_array($userimport)">                            <volist name="userimport" id="vo">                                <tr>                                    <td>{pigcms{$vo.phone}</td>                                    <td>{pigcms{$vo.money} {pigcms{$config['Currency_txt']}</td>                                    <td>{pigcms{$vo.score}</td>                                    <td>{pigcms{$vo.remark}</td>                                </tr>                            </volist>                            <tr><td class="textcenter pagebar" colspan="14">{pigcms{$pagebar}</td></tr>                            <else/>                            <tr><td class="textcenter red" colspan="14">列表为空！</td></tr>                        </if>                        </tbody>                    </table>                </div>            </form>            <if condition="is_array($userimport)">                <br>                <input type="button" value="确认导入" id="confirm" class="button"/>                <input type="button" value="取消" id="cancel" class="button"/>            </if>		</div><script type="text/javascript" src="{pigcms{$static_public}js/ajaxfileupload.js"></script><script type='text/javascript'>    $(document).ready(function(){        layer.config({extend: 'extend/layer.ext.js'});        $('#confirm').click(function(){            layer.confirm('确定导入吗?', {icon: 3, title:'提示',offset: ['100px', '400px'],}, function(index){                $.get('{pigcms{:U("User/importmoney")}',{import: 2},function(res){                    layer.msg('已导入');                    setTimeout(function () {window.location.href="{pigcms{:U('User/importmoneylist')}"; }, 1000);                },'json');                layer.close(index);            });        });        $('#cancel').click(function(){            layer.confirm('确定取消吗?', {icon: 3, title:'提示',offset: ['100px', '400px'],}, function(index){                $.get('{pigcms{:U("User/importmoney")}',{import: 3},function(res){                    layer.msg('已取消');                    setTimeout(function () {window.location.reload() }, 1000);                },'json');                layer.close(index);            });        });    });// 上传excel 表格function ExcelImport(){       $.ajaxFileUpload({       url:"{pigcms{:U('User/execimportmoney')}",    //需要链接到服务器地址       secureuri:false,       fileElementId:'excelimport',                 //文件选择框的id属性       dataType: 'json',       success: function (data) {       if(data.error){		   alert(data.msg);	    }else{			 alert('导入成功！');			 window.location.href="{pigcms{:U('User/importmoney')}&import=1";		   }		   $("#excelimport").change(function(){                 ExcelImport();                       });        }      });   }  $("#excelimport").change(function(){           ExcelImport();                 });</script><include file="Public:footer"/>